import{_ as a,o as e,c as r,a5 as d}from"./chunks/framework.BF53ZjCA.js";const m=JSON.parse('{"title":"作品档案与图像证据","description":"","frontmatter":{"title":"作品档案与图像证据","gallery":"archive-reading"},"headers":[],"relativePath":"zh/gallery/archive-reading.md","filePath":"zh/gallery/archive-reading.md","lastUpdated":1789230763000}'),i={name:"zh/gallery/archive-reading.md"};function l(h,t,o,n,c,s){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="作品档案与图像证据" tabindex="-1">作品档案与图像证据 <a class="header-anchor" href="#作品档案与图像证据" aria-label="Permalink to &quot;作品档案与图像证据&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>一张图片不一定等于一件独立作品：它可能是展柜照片、历史插图、同一宝石的另一状态， 也可能只是为了观察工艺而建立的关联视角。本页提供阅读画廊档案的基本方法。</p><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>先分清对象来源与图像来源：前者回答“这是什么”，后者回答“这张图由谁拍摄、以何种许可使用”。</li><li>年代字段描述对象、设计或再切割事件时，会明确写出对应关系；它不自动等于照片拍摄年份。</li><li>标有“档案关系”的卡片可能共享同一对象或图像，应按关联记录阅读，不重复计算为独立作品。</li><li>传奇宝石的重量、历史与馆藏信息属于档案事实；它们不能替代现代鉴定报告、分级报告或估值意见。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>作品</th><th>详情</th><th>备注</th></tr></thead><tbody><tr><td>Wittelsbach 钻石</td><td>再切割前 / 后</td><td>同一颗宝石的关联档案状态</td></tr><tr><td>展柜照片</td><td>图像证据</td><td>不自动等于对象来源</td></tr><tr><td>历史插图</td><td>文献记录</td><td>单独记录来源与年代</td></tr></tbody></table><p><em>详见<a href="./intro.html">画廊总览</a>。</em></p>',8)])])}const p=a(i,[["render",l]]);export{m as __pageData,p as default};
